/**
Write "Congratulations, <username>!" to a buffer. The buffer will be printed by the caller.

@param buffer: the buffer to write to
@param buffer_size: the size of the buffer
@param userName: the username to congratulate
@param userName_size: the maximum number of characters to read from userName
*/
void congratulate_user(char* buffer, int buffer_size, const char *userName, int userName_size)
{
    // Use snprintf to safely write the formatted string to the buffer.
    // The %.*s format specifier is used to print at most userName_size characters from userName.
    // This approach is robust as it handles cases where userName might not be null-terminated
    // or where userName_size specifies an explicit maximum length to read from userName.
    // snprintf ensures that the buffer will not be overflowed and will always be null-terminated
    // as long as buffer_size is greater than 0.
    snprintf(buffer, buffer_size, "Congratulations, %.*s!", userName_size, userName);
}
